class Solution {
public:
    int pivotIndex(vector<int>& nums) {
        int size = nums.size();
        int tsum = 0;
        for(int i=0;i<size;i++){
            tsum = tsum+nums[i];
        }

        int lsum = 0;
        int rsum = tsum;

        for(int i=0;i<size;i++){

            if(lsum==rsum){
                return i-1;
            }
            lsum = lsum+nums[i-1];
            rsum = tsum-lsum-nums[i];

        }

        return -1;
    }
};
